javas.java:

boolean def withinCatalog(str:medicalCategory) {
    if (medicalCategory == "DRUG_C") {
        return false;
    } else {
        return true;
    }
}


double def deductible(str:insuranceType, str:hospitalLevel, boolean:emergency) {
    if (insuranceType == "EMPLOYEE") {
        if (emergency) {
            if (hospitalLevel == "THIRD_A") {
                return 400.0;
            } else if (hospitalLevel == "SECOND_A") {
                return 250.0;
            } else {
                return 100.0;
            }
        } else {
            if (hospitalLevel == "THIRD_A") {
                return 800.0;
            } else if (hospitalLevel == "SECOND_A") {
                return 500.0;
            } else {
                return 200.0;
            }
        }
    } else {
        if (emergency) {
            if (hospitalLevel == "THIRD_A") {
                return 300.0;
            } else if (hospitalLevel == "SECOND_A") {
                return 150.0;
            } else {
                return 50.0;
            }
        } else {
            if (hospitalLevel == "THIRD_A") {
                return 600.0;
            } else if (hospitalLevel == "SECOND_A") {
                return 300.0;
            } else {
                return 100.0;
            }
        }
    }
}


double def reimburseRatio(str:insuranceType, str:hospitalLevel, boolean:emergency) {
    double ratio = 0.6;
    if (insuranceType == "EMPLOYEE") {
        if (hospitalLevel == "THIRD_A") {
            ratio = 0.9;
        } else if (hospitalLevel == "SECOND_A") {
            ratio = 0.85;
        } else {
            ratio = 0.8;
        }
    } else {
        if (hospitalLevel == "THIRD_A") {
            ratio = 0.7;
        } else if (hospitalLevel == "SECOND_A") {
            ratio = 0.65;
        } else {
            ratio = 0.6;
        }
    }
    if (emergency) {
        ratio = ratio + 0.05;
    }
    if (ratio > 1.0) {
        ratio = 1.0;
    }
    return ratio;
}


double def prepaidSelfPay(str:medicalCategory, double:totalExpense) {
    if (medicalCategory == "DRUG_B") {
        return totalExpense * 0.1;
    } else {
        return 0.0;
    }
}


double def annualCap(str:insuranceType) {
    if (insuranceType == "EMPLOYEE") {
        return 300000.0;
    } else {
        return 200000.0;
    }
}


double def applyCap(double:payableAmount, double:remainingCap) {
    if (remainingCap <= 0.0) {
        return 0.0;
    } else if (payableAmount > remainingCap) {
        return remainingCap;
    } else {
        return payableAmount;
    }
}


str def complianceResult(boolean:withinCatalog, boolean:offSite, boolean:filed) {
    if (withinCatalog == false) {
        return "SELF_PAY";
    } else if (offSite && filed == false) {
        return "MANUAL_REVIEW";
    } else {
        return "APPROVE";
    }
}


boolean def needManualReview(str:result, double:payableAmount) {
    if (result == "MANUAL_REVIEW") {
        return true;
    } else if (result == "APPROVE" && payableAmount >= 50000.0) {
        return true;
    } else {
        return false;
    }
}
